// Control Flag (Set to 0 for zero runtime cost)
#define APP_DEBUG_LEVEL 1 

#if APP_DEBUG_LEVEL > 0
#define DEBUG_LOG(fmt, ...) \
    fprintf(stderr, "[DBG] " fmt "\n", __VA_ARGS__)
#else
#define DEBUG_LOG(fmt, ...) ((void)0)
#endif

void execute_task(int value) {
    DEBUG_LOG("Starting task with value: %d", value);
    if (value > 100) {
        DEBUG_LOG("Value exceeds threshold.");
    }
    // ... core logic ...
}

// Compiler optimizes away DEBUG_LOG if APP_DEBUG_LEVEL is 0.
